	agent := New()
	cases := []struct {
		event      string
		wantType   int
		wantPrompt string
		wantResp   string
	}{
		{"SessionStart", 1, "", ""},
		{"UserPromptSubmit", 2, "Use the shell to run the command: echo hi > hi.txt and then reply done", ""},
		{"Stop", 3, "", "done"},
