```go
// WriteSession persists native session bytes at the ref Entire resolved —
// but never over sarvam's own rollout store. A native rollout is sarvam's
// append-only transcript; replacing one with an entire-captured snapshot
// would truncate live appends or clobber history, which redaction cannot
// undo. A rollout-shaped ref that does not exist yet is the restore case —
// Entire recreating a captured snapshot on a fresh clone — so it is allowed
// to be written once. An empty payload is not a snapshot at all, and an
// empty ref resolves to the deterministic store path rather than
// ResolveSessionFile, which prefers the native file.
func (a *Agent) WriteSession(session protocol.AgentSessionJSON) error {
	if len(session.NativeData) == 0 {
		return errEmptySessionData
	}
	ref := strings.TrimSpace(session.SessionRef)
	if ref == "" {
		if strings.TrimSpace(session.SessionID) == "" {
			return errMissingSessionRef
		}
		ref = a.storePath(session.SessionID)
	}
	if isNativeRolloutPath(ref) {
		if _, err := os.Stat(ref); err == nil {
			return errNativeRolloutWrite
		}
		// The rollout does not exist yet: this is Entire restoring a
		// captured snapshot onto a fresh clone, not clobbering a live
		// transcript.
