```go
// readRolloutLines parses the rollout JSONL for a live transcript:
// unparseable lines become empty placeholders so line offsets stay aligned
// with the physical file, and a final line that is still being written (no
// trailing newline) is excluded — the position must not cover a record
// whose remaining bytes arrive later, or the next read at that offset
// would skip them.
func readRolloutLines(path string) ([]rolloutLine, error) {
	return scanRolloutLines(path, false)
}

// readFinishedRolloutLines parses a rollout snapshot whose writer is done:
// a final line without a trailing newline is complete data — typically the
// last assistant reply — and is kept when it parses. Redaction does not
// guarantee the trailing newline survives, so the strict rule would drop
// the final record from a compacted transcript.
func readFinishedRolloutLines(path string) ([]rolloutLine, error) {
	return scanRolloutLines(path, true)
}

func scanRolloutLines(path string, lenientFinal bool) ([]rolloutLine, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer func() { _ = f.Close() }()

	var lines []rolloutLine
	reader := bufio.NewReaderSize(f, 64*1024)
	for {
		raw, readErr := reader.ReadBytes('\n')
		if len(raw) > 0 {
			line := strings.TrimSpace(string(raw))
			var record rolloutLine
			parses := json.Unmarshal([]byte(line), &record) == nil
			if !parses {
				record = rolloutLine{}
			}
			if readErr == nil || (lenientFinal && parses) {
				lines = append(lines, record)
			}
		}
		if readErr != nil {
			if errors.Is(readErr, io.EOF) {
				return lines, nil
			}
			return lines, readErr
		}
	}
}
```

